// ignore_for_file: avoid_print, curly_braces_in_flow_control_structures, unused_element, unnecessary_cast

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:veil_mobile/core/veil/veil_runtime_evaluator.dart';
import 'package:veil_mobile/core/veil/veil_segment.dart';
import 'package:veil_mobile/core/veil/veil_segment_type.dart';
import 'package:veil_mobile/core/veil/veil_track.dart';
import 'package:veil_mobile/core/veil/veil_track_codec.dart';

const _root = 'docs/spec_0_1/conformance';
void main() {
  test('executes the Spec 0.1 corpus with declared Mobile capabilities', () {
    final manifest = _json('$_root/manifest.json');
    final ids = (manifest['vectorIds'] as List).cast<String>();
    final vectors = <String, Map<String, dynamic>>{};
    for (final file in Directory(
      _root,
    ).listSync(recursive: true).whereType<File>()) {
      if (!file.path.endsWith('.json') || file.path.endsWith('manifest.json'))
        continue;
      final value = jsonDecode(file.readAsStringSync());
      if (value is Map<String, dynamic> && value['id'] is String) {
        vectors[value['id'] as String] = value;
      }
    }
    final expectedCounts = (manifest['vectorCountByCategory'] as Map).map(
      (key, value) => MapEntry(key.toString(), (value as num).toInt()),
    );
    final actualCounts = <String, int>{};
    for (final id in ids) {
      final category = vectors[id]?['category'];
      if (category != null)
        actualCounts[category as String] = (actualCounts[category] ?? 0) + 1;
    }
    expect(vectors.keys, containsAll(ids));
    expect(ids.length, manifest['totalVectorCount']);
    for (final entry in expectedCounts.entries) {
      if (entry.key != 'total') expect(actualCounts[entry.key], entry.value);
    }

    final fixtureById = _fixtures();
    final counts = <String, int>{
      'PASS': 0,
      'FAIL': 0,
      'N/A': 0,
      'UNTESTABLE': 0,
    };
    final categories = <String, Map<String, int>>{};
    final capabilityCounts = <String, Map<String, int>>{};
    final differences = <String>[];

    for (final id in ids) {
      final vector = vectors[id]!;
      final category = vector['category'] as String;
      final applies = (vector['appliesTo'] as List? ?? const []).cast<String>();
      final result = _runFinal(id, vector, applies, fixtureById);
      counts[result.status] = (counts[result.status] ?? 0) + 1;
      final bucket = categories.putIfAbsent(category, () => _emptyCounts());
      bucket[result.status] = (bucket[result.status] ?? 0) + 1;
      for (final capability in applies) {
        final cap = capabilityCounts.putIfAbsent(
          capability,
          () => _emptyCounts(),
        );
        cap[result.status] = (cap[result.status] ?? 0) + 1;
      }
      print(
        'VECTOR ${result.status} | $id | expected=${result.expected} | observed=${result.observed}',
      );
      if (result.status == 'FAIL' || result.status == 'UNTESTABLE') {
        differences.add(
          '$id | ${result.expected} | ${result.observed} | ${result.classification}',
        );
      }
    }
    print('SPEC 0.1 CORPUS: ${ids.length} vectors');
    print('RESULTS: $counts');
    print('BY CATEGORY: $categories');
    print('BY CAPABILITY: $capabilityCounts');
    for (final difference in differences) print('DIFFERENCE: $difference');
    expect(ids.length, 113);
  });
}

Map<String, int> _emptyCounts() => {
  'PASS': 0,
  'FAIL': 0,
  'N/A': 0,
  'UNTESTABLE': 0,
};

