_Result _normalization(Map<String, dynamic> vector) {
  final id = vector['id'] as String;
  final input = vector['input'] as Map<String, dynamic>;
  if (id.startsWith('normalization.skip.')) {
    return const _Result(
      'UNTESTABLE',
      'effective runtime seek outcome',
      'controller observation seam unavailable',
      'D - TEST_ADAPTER_GAP',
    );
  }
  if (id.startsWith('normalization.track-metadata.')) {
    final base = _json('$_root/serialization/valid/minimal-local.veil');
    base['trackMetadata'] = input['trackMetadata'] ?? const {};
    final track = VeilTrackCodec.tryDecode(jsonEncode(base));
    if (track == null)
      return const _Result(
        'FAIL',
        'writer-normalized metadata',
        'REJECT_DOCUMENT',
        'A - IMPLEMENTATION DEFECT / FUTURE MIGRATION REQUIRED',
      );
    final output =
        jsonDecode(VeilTrackCodec.encode(track)) as Map<String, dynamic>;
    final observed = output['trackMetadata'];
    final wanted = (vector['expected'] as Map)['trackMetadata'];
    final pass =
        wanted is Map &&
        observed is Map &&
        (wanted as Map).entries.every(
          (entry) => observed[entry.key] == entry.value,
        );
    return _Result(
      pass ? 'PASS' : 'FAIL',
      jsonEncode(wanted),
      jsonEncode(observed),
      pass ? '' : 'B - EXPECTED HISTORICAL BEHAVIOR DIFFERENCE',
    );
  }
  final base = _json('$_root/serialization/valid/minimal-local.veil');
  base['items'] = input['items'] ?? const [];
  final track = VeilTrackCodec.tryDecode(jsonEncode(base));
  if (track == null)
    return const _Result(
      'FAIL',
      'normalized bookmark',
      'REJECT_DOCUMENT',
      'A - IMPLEMENTATION DEFECT / FUTURE MIGRATION REQUIRED',
    );
  final observed = track.segments
      .map(
        (segment) => <String, dynamic>{
          'id': segment.id,
          'type': segment.type.toJson(),
          'start': segment.startMs / 1000,
          'end': segment.endMs / 1000,
          'enabled': segment.enabled,
          if (segment.label != null) 'label': segment.label,
          if (segment.notes != null) 'notes': segment.notes,
          if (segment.type == VeilSegmentType.bookmark) 'locked': false,
        },
      )
      .toList();
  final wanted = vector['expected'];
  final pass = _containsExpected(wanted, observed);
  return _Result(
    pass ? 'PASS' : 'FAIL',
    jsonEncode(wanted),
    jsonEncode(observed),
    pass ? '' : 'B - EXPECTED HISTORICAL BEHAVIOR DIFFERENCE',
  );
}

_Result _runtime(Map<String, dynamic> vector) {
  final input = vector['input'] as Map<String, dynamic>;
  final timeline = input['timeline'] as Map<String, dynamic>?;
  if (timeline == null)
    return const _Result(
      'UNTESTABLE',
      'runtime trace',
      'no timeline',
      'D - EVIDENCE REQUIRED',
    );
  final state = input['initialState'] as Map<String, dynamic>? ?? const {};
  final offset = (state['globalOffsetSeconds'] as num? ?? 0).toDouble();
  VeilTrack track = _trackFromTimeline(timeline, offset);
  var position = (state['position'] as num? ?? 0).toDouble();
  final observed = <Map<String, dynamic>>[];
  for (final event
      in (input['events'] as List? ?? const [])
          .whereType<Map<String, dynamic>>()) {
    final type = event['type'];
    if (type == 'POSITION') position = (event['time'] as num).toDouble();
    if (type == 'USER_SEEK') position = (event['target'] as num).toDouble();
    if (type == 'TIMELINE_CHANGE' &&
        event['timeline'] is Map<String, dynamic>) {
      track = _trackFromTimeline(
        event['timeline'] as Map<String, dynamic>,
        offset,
      );
    }
    final positionMs = (position * 1000).round();
    final active = VeilRuntimeEvaluator.activeSegmentsAt(track, positionMs);
    final effectiveMs = positionMs + (offset * 1000).round();
    final bookmarks = track.segments
        .where(
          (segment) =>
              segment.type == VeilSegmentType.bookmark &&
              segment.enabled &&
              segment.startMs == effectiveMs,
        )
        .toList();
    final actionTypes = <String>[];
    if (active.any((segment) => segment.type == VeilSegmentType.mask))
      actionTypes.add('MASK_ACTIVE');
    if (VeilRuntimeEvaluator.hasActiveMute(active))
      actionTypes.add('MUTE_ACTIVE');
    if (bookmarks.isNotEmpty) actionTypes.add('BOOKMARK_AVAILABLE');
    observed.add({
      'actionTypes': actionTypes,
      'activeIds': active.map((s) => s.id).toList(),
    });
  }
  if (track.segments.any((s) => s.type == VeilSegmentType.skip)) {
    return _Result(
      'UNTESTABLE',
      jsonEncode(vector['expected']),
      jsonEncode(observed),
      'D - EVIDENCE REQUIRED (skip seek side effects require a video-controller adapter)',
    );
  }
  final expectedTrace =
      (vector['expected'] as Map<String, dynamic>)['trace'] as List;
  final pass =
      observed.length == expectedTrace.length &&
      observed.asMap().entries.every((entry) {
        final actions = (expectedTrace[entry.key] as Map)['actions'] as List;
        final expectedType = (actions.first as Map)['type'] as String;
        final actual = (entry.value['actionTypes'] as List).cast<String>();
        if (expectedType.endsWith('_ACTIVE') ||
            expectedType == 'BOOKMARK_AVAILABLE')
          return actual.contains(expectedType);
        if (expectedType.endsWith('_INACTIVE') || expectedType == 'NO_ACTION')
          return actual.isEmpty;
        return false;
      });
  return _Result(
    pass ? 'PASS' : 'FAIL',
    jsonEncode(expectedTrace),
    jsonEncode(observed),
    pass ? '' : 'B - EXPECTED HISTORICAL BEHAVIOR DIFFERENCE',
  );
}

VeilTrack _trackFromTimeline(Map<String, dynamic> timeline, double offset) =>
    VeilTrack.empty().copyWith(
      globalOffsetSeconds: offset,
      segments: (timeline['items'] as List? ?? const [])
          .whereType<Map<String, dynamic>>()
          .map(_segment)
          .toList(),
    );
_Result _identity(Map<String, dynamic> vector) {
  final input = vector['input'] as Map<String, dynamic>;
  final wanted = (vector['expected'] as Map)['identityStatus'] as String;
  final loaded = _identityMap(input['loadedMediaIdentity']);
  if (input['timelineBinding'] == 'unbound' ||
      input['timelineBinding'] == 'manual-unbound' ||
      loaded == null) {
    return _Result(
      wanted == 'UNKNOWN' ? 'PASS' : 'FAIL',
      wanted,
      'UNKNOWN',
      wanted == 'UNKNOWN'
          ? ''
          : 'A - IMPLEMENTATION DEFECT / FUTURE MIGRATION REQUIRED',
    );
  }
  final base = VeilTrackCodec.tryDecode(
    File(
      '$_root/serialization/valid/metadata-v1-local.veil',
    ).readAsStringSync(),
  );
  if (base == null)
    return const _Result(
      'UNTESTABLE',
      'identityStatus',
      'missing local identity surface',
      'D - EVIDENCE REQUIRED',
    );
  final resolution = loaded['resolution'] as Map;
  final result = VeilTrackCodec.mediaIdentityMatches(
    track: base,
    fileName: loaded['name'] as String,
    fileSize: (loaded['fileSize'] as num).toInt(),
    durationSeconds: (loaded['duration'] as num).toDouble(),
    width: (resolution['width'] as num).toInt(),
    height: (resolution['height'] as num).toInt(),
    loadedFingerprintValue:
        ((loaded['fingerprint'] as Map?)?['value']) as String?,
  );
  final observed = result == null
      ? 'UNKNOWN'
      : result
      ? 'MATCH'
      : 'MISMATCH';
  return _Result(
    observed == wanted ? 'PASS' : 'FAIL',
    wanted,
    observed,
    observed == wanted
        ? ''
        : 'A - IMPLEMENTATION DEFECT / FUTURE MIGRATION REQUIRED',
  );
}

Map<String, dynamic>? _identityMap(dynamic value) =>
    value is Map<String, dynamic> ? value : null;

bool _containsExpected(dynamic expected, dynamic observed) {
  final candidate = expected is Map && expected['items'] is List
      ? expected['items']
      : expected;
  return _semanticEquals(candidate, observed);
}

bool _semanticEquals(dynamic left, dynamic right) {
  if (left is num && right is num) return left == right;
  if (left is List && right is List)
    return left.length == right.length &&
        left.asMap().entries.every(
          (entry) => _semanticEquals(entry.value, right[entry.key]),
        );
  if (left is Map && right is Map) {
    final keys = left.keys.toSet();
    return keys.length == right.keys.toSet().length &&
        keys.every(
          (key) =>
              right.containsKey(key) && _semanticEquals(left[key], right[key]),
        );
  }
  return left == right;
}

VeilSegment _segment(Map<String, dynamic> item) => VeilSegment(
  id: item['id'] as String? ?? 'vector',
  type: VeilSegmentType.fromJson(item['type'] as String),
  startMs: (((item['start'] as num?) ?? 0).toDouble() * 1000).round(),
  endMs:
      (((item['end'] as num?) ?? (item['start'] as num? ?? 0)).toDouble() *
              1000)
          .round(),
  enabled: item['enabled'] as bool? ?? true,
);

Map<String, dynamic> _json(String path) =>
    jsonDecode(File(path).readAsStringSync()) as Map<String, dynamic>;

Map<String, String> _fixtures() {
  final result = <String, String>{};
  for (final file in Directory(
    _root,
  ).listSync(recursive: true).whereType<File>()) {
    if (!file.path.endsWith('.veil')) continue;
    final relative = file.path
        .replaceAll('\\', '/')
        .split('docs/spec_0_1/conformance/')
        .last;
    final parts = relative.split('/');
    final name = parts.last.substring(0, parts.last.length - 5);
    result['${parts.sublist(0, parts.length - 1).join('.')}.$name'] = file.path;
  }
  return result;
}

_Result _runFinal(
  String id,
  Map<String, dynamic> vector,
  List<String> applies,
  Map<String, String> fixtures,
) {
  if (id.contains('youtube') ||
      applies.any(
        (value) => value == 'provider' || value.contains('youtube'),
      )) {
    return const _Result(
      'N/A',
      'provider capability',
      'not claimed by Mobile',
      'CAPABILITY_NOT_CLAIMED',
    );
  }
  return switch (vector['category']) {
    'serialization' => _serializationFinal(vector),
    'normalization' => _normalizationFinal(vector),
    'runtime' => _runtimeFinal(vector),
    'media_identity' => _identity(vector),
    'security' => _securityFinal(vector),
    _ => const _Result('FAIL', 'known category', 'unknown', 'HARNESS_ERROR'),
  };
}

_Result _serializationFinal(Map<String, dynamic> vector) {
  final input = vector['input'] as Map<String, dynamic>;
  final fixture = input['fixture'] as String;
  final source = File('$_root/$fixture').readAsStringSync();
  final expected = (vector['expected'] as Map)['parserStatus'] as String;
  final parsed = VeilTrackCodec.parseCanonical(source);
  var pass = parsed.status.wireName == expected;
  final roundTrip = (vector['expected'] as Map)['roundTrip'];
  if (pass && roundTrip is Map && parsed.track != null) {
    final before = jsonDecode(source);
    final after = jsonDecode(VeilTrackCodec.encode(parsed.track!));
    for (final path in (roundTrip['preservePaths'] as List).cast<String>()) {
      pass =
          pass && _semanticEquals(_atPath(before, path), _atPath(after, path));
    }
  }
  return _Result(
    pass ? 'PASS' : 'FAIL',
    expected,
    parsed.status.wireName,
    pass ? '' : 'IMPLEMENTATION_DEFECT',
  );
}

dynamic _atPath(dynamic value, String path) {
  if (path == r'$.futureRoot') return (value as Map)['futureRoot'];
  if (path == r'$.items[0]') return ((value as Map)['items'] as List)[0];
  throw FormatException('Unsupported harness path: $path');
}

_Result _normalizationFinal(Map<String, dynamic> vector) {
  final id = vector['id'] as String;
  if (!id.startsWith('normalization.skip.')) return _normalization(vector);
  final input = vector['input'] as Map<String, dynamic>;
  final track = _trackFromTimeline({'items': input['items']}, 0);
  final observed = VeilRuntimeEvaluator.normalizedSkipClusters(track)
      .map(
        (cluster) => {
          'start': cluster.startMs / 1000,
          'end': cluster.endMs / 1000,
        },
      )
      .toList();
  final wanted = (vector['expected'] as Map)['skipClusters'];
  final pass = _semanticEquals(wanted, observed);
  return _Result(
    pass ? 'PASS' : 'FAIL',
    jsonEncode(wanted),
    jsonEncode(observed),
    pass ? '' : 'IMPLEMENTATION_DEFECT',
  );
}

_Result _runtimeFinal(Map<String, dynamic> vector) {
  final input = vector['input'] as Map<String, dynamic>;
  final timeline = input['timeline'] as Map<String, dynamic>?;
  if (timeline == null) {
    return const _Result('FAIL', 'timeline', 'missing', 'HARNESS_ERROR');
  }
  final trackState = input['initialState'] as Map<String, dynamic>? ?? const {};
  final offset = (trackState['globalOffsetSeconds'] as num? ?? 0).toDouble();
  var track = _trackFromTimeline(timeline, offset);
  final hasSkip = track.segments.any(
    (item) => item.type == VeilSegmentType.skip,
  );
  if (!hasSkip) return _runtime(vector);

  var position = (trackState['position'] as num? ?? 0).toDouble();
  var playing = trackState['playbackState'] == 'playing';
  final effectiveDuration = trackState['effectiveMediaDuration'] as num?;
  final hostDurationMs = effectiveDuration == null
      ? null
      : ((effectiveDuration.toDouble() - offset) * 1000).round();
  String? lastClusterKey;
  final observed = <Map<String, dynamic>>[];
  final events = (input['events'] as List? ?? const [])
      .whereType<Map<String, dynamic>>()
      .toList();
  for (var index = 0; index < events.length; index++) {
    final event = events[index];
    final type = event['type'];
    if (type == 'POSITION') position = (event['time'] as num).toDouble();
    if (type == 'USER_SEEK') {
      position = (event['target'] as num).toDouble();
      lastClusterKey = null;
    }
    if (type == 'RESUME') {
      playing = true;
      lastClusterKey = null;
    }
    if (type == 'PAUSE') playing = false;
    if (type == 'TIMELINE_CHANGE' &&
        event['timeline'] is Map<String, dynamic>) {
      track = _trackFromTimeline(
        event['timeline'] as Map<String, dynamic>,
        offset,
      );
      lastClusterKey = null;
    }
    final cluster = VeilRuntimeEvaluator.activeSkipClusterAt(
      track,
      (position * 1000).round(),
    );
    Map<String, dynamic> action = {'type': 'NO_ACTION'};
    if (playing && cluster != null && cluster.runtimeKey != lastClusterKey) {
      final targetMs = VeilRuntimeEvaluator.skipHostTargetMs(
        track: track,
        cluster: cluster,
        hostDurationMs: hostDurationMs,
      );
      position = targetMs / 1000;
      lastClusterKey = cluster.runtimeKey;
      action = {'type': 'SEEK_TO', 'target': position};
    } else if (cluster == null) {
      lastClusterKey = null;
    }
    observed.add({
      'eventIndex': index,
      'actions': [action],
    });
  }
  final wanted = (vector['expected'] as Map)['trace'];
  final pass = _semanticEquals(wanted, observed);
  return _Result(
    pass ? 'PASS' : 'FAIL',
    jsonEncode(wanted),
    jsonEncode(observed),
    pass ? '' : 'IMPLEMENTATION_DEFECT',
  );
}

_Result _securityFinal(Map<String, dynamic> vector) {
  final id = vector['id'] as String;
  final input = vector['input'] as Map<String, dynamic>;
  if (id == 'security.skip-overlap-stress') {
    final track = _trackFromTimeline({'items': input['items']}, 0);
    final observed = VeilRuntimeEvaluator.normalizedSkipClusters(track)
        .map(
          (cluster) => {
            'start': cluster.startMs / 1000,
            'end': cluster.endMs / 1000,
          },
        )
        .toList();
    final wanted = (vector['expected'] as Map)['expectedSkipClusters'];
    final pass = _semanticEquals(wanted, observed);
    return _Result(
      pass ? 'PASS' : 'FAIL',
      jsonEncode(wanted),
      jsonEncode(observed),
      pass ? '' : 'IMPLEMENTATION_DEFECT',
    );
  }
  if (id == 'security.zero-progress-skip-loop') return _runtimeFinal(vector);

  String source;
  VeilResourcePolicy policy = const VeilResourcePolicy();
  if (input['rawText'] is String) {
    source = input['rawText'] as String;
  } else if (input['document'] != null) {
    source = jsonEncode(input['document']);
    final configured =
        input['resourcePolicy'] as Map<String, dynamic>? ?? const {};
    policy = VeilResourcePolicy(
      maxItems:
          (configured['maxItems'] as num?)?.toInt() ?? VeilTrackCodec.maxItems,
      maxNestingDepth:
          (configured['maxNestingDepth'] as num?)?.toInt() ??
          VeilTrackCodec.maxJsonDepth,
      maxStringBytes:
          (configured['maxStringLength'] as num?)?.toInt() ??
          VeilTrackCodec.maxStringBytes,
    );
  } else {
    source = File('$_root/${input['fixture']}').readAsStringSync();
  }
  final parsed = VeilTrackCodec.parseCanonical(source, policy: policy);
  final wanted = (vector['expected'] as Map)['parserStatus'] as String;
  final nestingAlternative =
      id == 'security.limit.nesting' &&
      parsed.status == VeilParseStatus.rejectDocument;
  final pass = parsed.status.wireName == wanted || nestingAlternative;
  return _Result(
    pass ? 'PASS' : 'FAIL',
    wanted,
    parsed.status.wireName,
    pass ? '' : 'IMPLEMENTATION_DEFECT',
  );
}

class _Result {
  const _Result(this.status, this.expected, this.observed, this.classification);
  final String status;
  final String expected;
  final String observed;
  final String classification;
}
